        scannedBatch: batch,
        currentBatch: batch,
        isStale: false,
        staleReason: '',
        queueStates: const {},
        logs: const [],
        progressBatches: progressBatches.isEmpty ? [batch] : progressBatches,
        runSessions: const [],
        activeSessions: const [],
